-- ============================================
-- LUMA — Oz Tome 6 (FINAL) : Chapitres XXI-XXIV — De la forêt du Lion Roi au retour au Kansas
-- Texte original, domaine public
-- ============================================


with s as (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true),
     lang as (select id from languages where code = 'en')
insert into books (language_id, title, theme, description, cecr_level, cover_emoji, total_pages, position, series_id, volume_number)
select lang.id, 'Tome 6 : Le retour au Kansas', 'Classique • L. Frank Baum (1900)', 'Le Lion devient roi de la forêt, les amis franchissent la colline des Têtes-Marteaux, Glinda exauce enfin le vœu de Dorothy, et elle retrouve Tante Em au Kansas.', 'B1', '🏡', 3, 1, s.id, 6
from lang, s;


with b as (select id from books where title = 'Tome 6 : Le retour au Kansas' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 1, '[{"en": "They entered a magnificent old forest where the Lion declared, ''This forest is perfectly delightful. Never have I seen a more beautiful place. I should like to live here all my life.''", "fr": "Ils entrèrent dans une magnifique vieille forêt où le Lion déclara : ''Cette forêt est absolument délicieuse. Je n''ai jamais vu un plus bel endroit. J''aimerais vivre ici toute ma vie.''"}, {"en": "They came upon hundreds of wild beasts gathered together, snarling and growling. ''Welcome, O King of Beasts!'' said the biggest tiger, bowing to the Lion. ''You have come in good time to fight our enemy and bring peace to us once more.''", "fr": "Ils tombèrent sur des centaines de bêtes sauvages rassemblées, grognant et rugissant. ''Bienvenue, ô Roi des Bêtes !'' dit le plus grand tigre, s''inclinant devant le Lion. ''Vous êtes arrivé au bon moment pour combattre notre ennemi et nous ramener la paix.''"}, {"en": "A monstrous spider, big as an elephant with legs as long as tree trunks, had been devouring the animals of the forest. ''If I put an end to your enemy, will you obey me as King of the Forest?'' asked the Lion. ''We will do that gladly,'' the beasts roared.", "fr": "Une araignée monstrueuse, grosse comme un éléphant avec des pattes longues comme des troncs d''arbre, dévorait les animaux de la forêt. ''Si je mets fin à votre ennemi, m''obéirez-vous comme Roi de la Forêt ?'' demanda le Lion. ''Nous le ferons avec joie,'' rugirent les bêtes."}, {"en": "The Lion found the spider asleep, and knowing its neck was slender as a wasp''s waist, he sprang directly onto its back and knocked its head clean off with one blow of his powerful paw.", "fr": "Le Lion trouva l''araignée endormie, et sachant que son cou était fin comme une taille de guêpe, il bondit directement sur son dos et lui fit sauter la tête d''un seul coup de sa puissante patte."}, {"en": "''You need fear your enemy no longer,'' the Lion announced proudly, and all the beasts bowed down to him as their King. He promised to return and rule over them once Dorothy was safely on her way home.", "fr": "''Vous n''avez plus besoin de craindre votre ennemi,'' annonça fièrement le Lion, et toutes les bêtes s''inclinèrent devant lui comme leur Roi. Il promit de revenir régner sur elles une fois Dorothy en sécurité sur le chemin de la maison."}, {"en": "At a steep, rocky hill, an armless creature called a Hammer-Head shot his flat head forward on an elastic neck, sending the Scarecrow tumbling down the hill. The Lion tried too, but was struck the same way.", "fr": "Sur une colline raide et rocheuse, une créature sans bras appelée Tête-Marteau projeta sa tête plate en avant sur un cou élastique, envoyant l''Épouvantail dévaler la colline. Le Lion essaya aussi, mais fut frappé de la même façon."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 6 : Le retour au Kansas' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 2, '[{"en": "''Call the Winged Monkeys,'' suggested the Tin Woodman. ''You have still the right to command them once more.'' Dorothy summoned them, and they carried the whole party safely over the hill of laughing Hammer-Heads.", "fr": "''Appelez les Singes Ailés,'' suggéra l''Homme de Fer-Blanc. ''Vous avez encore le droit de leur donner un ordre une fois de plus.'' Dorothy les convoqua, et ils portèrent tout le groupe en sécurité par-dessus la colline des Têtes-Marteaux hilares."}, {"en": "''This is the last time you can summon us,'' said their leader, ''so good-bye and good luck to you.'' They found themselves in the rich, happy country of the Quadlings, everything painted bright red.", "fr": "''C''est la dernière fois que vous pouvez nous convoquer,'' dit leur chef, ''donc au revoir et bonne chance.'' Ils se retrouvèrent dans le pays riche et heureux des Quadlings, où tout était peint en rouge vif."}, {"en": "A kind farmer''s wife gave them a good dinner. ''How far is it to the Castle of Glinda?'' asked Dorothy. ''Take the road to the South and you will soon reach it,'' she answered.", "fr": "Une gentille femme de fermier leur offrit un bon dîner. ''À quelle distance se trouve le Château de Glinda ?'' demanda Dorothy. ''Prenez la route vers le Sud et vous l''atteindrez bientôt,'' répondit-elle."}, {"en": "Glinda the Good Witch sat upon a throne of rubies, beautiful and kind. Dorothy told her the whole story. ''My greatest wish now is to get back to Kansas,'' she said, ''for Aunt Em will surely think something dreadful has happened to me.''", "fr": "Glinda la Bonne Sorcière était assise sur un trône de rubis, belle et bienveillante. Dorothy lui raconta toute l''histoire. ''Mon plus grand souhait maintenant est de retourner au Kansas,'' dit-elle, ''car Tante Em va sûrement penser qu''il m''est arrivé quelque chose de terrible.''"}, {"en": "''I am sure I can tell you of a way to get back to Kansas,'' said Glinda, ''but you must give me the Golden Cap.'' ''Willingly!'' exclaimed Dorothy. Glinda used its last three commands to send the Scarecrow, the Tin Woodman, and the Lion each to their own new kingdoms.", "fr": "''Je suis certaine de pouvoir vous dire un moyen de retourner au Kansas,'' dit Glinda, ''mais vous devez me donner le Bonnet d''Or.'' ''Volontiers !'' s''exclama Dorothy. Glinda utilisa ses trois derniers ordres pour envoyer l''Épouvantail, l''Homme de Fer-Blanc, et le Lion chacun vers leur nouveau royaume."}, {"en": "''Your Silver Shoes will carry you over the desert,'' Glinda revealed. ''If you had known their power you could have gone back to your Aunt Em the very first day.'' ''But then I should not have had my wonderful brains!'' cried the Scarecrow.", "fr": "''Vos Souliers d''Argent vous porteront au-dessus du désert,'' révéla Glinda. ''Si vous aviez connu leur pouvoir vous auriez pu retourner chez votre Tante Em dès le premier jour.'' ''Mais alors je n''aurais pas eu ma merveilleuse cervelle !'' s''écria l''Épouvantail."}]'::jsonb from b;


with b as (select id from books where title = 'Tome 6 : Le retour au Kansas' and series_id = (select id from books where title = 'The Wonderful Wizard of Oz' and is_series = true))
insert into book_pages (book_id, page_number, sentences)
select b.id, 3, '[{"en": "''All you have to do is to knock the heels together three times and command the shoes to carry you wherever you wish to go,'' explained Glinda. Dorothy hugged each of her friends tearfully, saying a sorrowful farewell.", "fr": "''Vous n''avez qu''à faire claquer les talons ensemble trois fois et ordonner aux souliers de vous emmener où vous voulez aller,'' expliqua Glinda. Dorothy serra chacun de ses amis en larmes, faisant des adieux déchirants."}, {"en": "Taking Toto in her arms, Dorothy clapped her heels together three times and said: ''Take me home to Aunt Em!'' Instantly she was whirling through the air, and after just three steps she found herself rolling on the Kansas prairie.", "fr": "Prenant Toto dans ses bras, Dorothy fit claquer ses talons trois fois et dit : ''Ramène-moi chez Tante Em !'' Instantanément elle tourbillonna dans les airs, et après seulement trois pas elle se retrouva à rouler sur la prairie du Kansas."}, {"en": "She was sitting on the broad Kansas prairie, right before the new farmhouse Uncle Henry had built after the cyclone. Her Silver Shoes had fallen off during the flight, lost forever in the desert.", "fr": "Elle était assise sur la vaste prairie du Kansas, juste devant la nouvelle ferme qu''Oncle Henry avait construite après le cyclone. Ses Souliers d''Argent étaient tombés pendant le vol, perdus à jamais dans le désert."}, {"en": "Aunt Em came out to water the cabbages and looked up to see Dorothy running toward her. ''My darling child!'' she cried, folding the little girl in her arms and covering her face with kisses. ''Where in the world did you come from?''", "fr": "Tante Em sortit arroser les choux et leva les yeux pour voir Dorothy courir vers elle. ''Mon enfant chérie !'' s''écria-t-elle, serrant la fillette dans ses bras et couvrant son visage de baisers. ''D''où viens-tu donc ?''"}, {"en": "''From the Land of Oz,'' said Dorothy gravely. ''And here is Toto, too. And oh, Aunt Em! I''m so glad to be at home again!''", "fr": "''Du Pays d''Oz,'' dit Dorothy gravement. ''Et voici Toto, aussi. Et oh, Tante Em ! Je suis si contente d''être de nouveau à la maison !''"}]'::jsonb from b;
